
#wowVersionBadge{display:none!important}
#scene{background-image:url("data:image/jpeg;base64,")!important;background-size:100% 100%!important;background-position:center!important;background-repeat:no-repeat!important}
.introBg{background-image:url("data:image/jpeg;base64,")!important;background-size:cover!important;background-position:center!important}
.introShade{background:linear-gradient(90deg,rgba(8,45,27,.18),rgba(8,45,27,.03) 55%,rgba(8,45,27,.10))!important}
.hot::after{content:attr(data-name)!important}
.hot{transition:transform .18s ease,box-shadow .18s ease!important}
.hot:hover{transform:translate(-50%,-50%) scale(1.16)!important}
#uiHits{position:fixed;inset:0;z-index:160;pointer-events:none}
.uiHit{position:absolute;display:block;border:0;background:transparent;cursor:pointer;pointer-events:auto;border-radius:16px}
.uiHit:focus-visible{outline:3px solid #ffe26b;outline-offset:2px}
.uiHit[data-tip]::after{content:attr(data-tip);position:absolute;left:50%;top:calc(100% + 8px);transform:translateX(-50%);background:rgba(15,58,39,.95);color:#fff;padding:6px 10px;border-radius:999px;font:800 11px Arial,sans-serif;white-space:nowrap;opacity:0;pointer-events:none;transition:.15s;z-index:300}
.uiHit:hover::after{opacity:1}
.overlay,.modal,.panel{z-index:500!important}
@media(max-width:900px){.uiHit[data-tip]::after{display:none}}
